import{_ as t,c as e,o as r,af as c}from"./chunks/framework.YlsIoeib.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"posts/最佳实践/前端已死.md","filePath":"posts/最佳实践/前端已死.md"}'),s={name:"posts/最佳实践/前端已死.md"};function p(i,a,o,h,n,l){return r(),e("div",null,a[0]||(a[0]=[c('<h2 id="一、为什么要分享这么一个主题" tabindex="-1">一、为什么要分享这么一个主题 <a class="header-anchor" href="#一、为什么要分享这么一个主题" aria-label="Permalink to “一、为什么要分享这么一个主题”">​</a></h2><p>这个话题非常的重要，前端都死了，还学这些vue3、hook、函数式有蛋用？岗位都没有了？你学得再好有什么用？更不用说，一群985/211的小孩要出来了，学历高，基础好，还年轻，最重要还便宜，我拿什么和他们拼？有什么优势和它们拼？</p><p>所以我在准备hook材料的时候，一直不得劲，如果只是为了完成KPI，毫无意义。</p><p>而导致我想法这么消极，就是因为我标题的前四个字前端已死，它让我一直处于一个焦虑状态。所以不聊不行！</p><p>首先来看一下这个话题形成的过程。</p><h2 id="二、话题形成的过程" tabindex="-1">二、话题形成的过程 <a class="header-anchor" href="#二、话题形成的过程" aria-label="Permalink to “二、话题形成的过程”">​</a></h2><h3 id="_2-1-话题起源" tabindex="-1">2.1 话题起源 <a class="header-anchor" href="#_2-1-话题起源" aria-label="Permalink to “2.1 话题起源”">​</a></h3><p><img src="https://secure2.wostatic.cn/static/gg2axXcpGUzDvs5nMBoneN/image.png?auth_key=1756541791-epreSV53tPo2QE8na3nViQ-0-ac44390d3067b29aefe093b3b57d18b5" alt=""></p><p><img src="https://secure2.wostatic.cn/static/u8BmYsJNvRNF7gvAbot1BQ/image.png?auth_key=1756541791-nhg7tsvCXB7dFpZojyaUsc-0-c51ab660858938e0b7faca8d57e89deb" alt=""></p><p>这个话题最近一次是在今年春季形成。源自于脉脉，当时脉脉上面出现一些前端已死的言论。</p><h3 id="_2-2-形成的过程" tabindex="-1">2.2 形成的过程 <a class="header-anchor" href="#_2-2-形成的过程" aria-label="Permalink to “2.2 形成的过程”">​</a></h3><p>![](<a href="https://secure2.wostatic.cn/static/9ZsgAvTvjw7Y25DH5zUZwA/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/9ZsgAvTvjw7Y25DH5zUZwA/Screenshot</a> 2023-08-23 at 15.56.54.png?auth_key=1756541791-uG1hYQdTw3pfWxHQZCxiEQ-0-dacf378e636c0c6360cbe5f025cc8cd8)</p><p>![](<a href="https://secure2.wostatic.cn/static/ofRhHEr7jB7th98zpAgXzf/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/ofRhHEr7jB7th98zpAgXzf/Screenshot</a> 2023-08-23 at 15.56.44.png?auth_key=1756541791-gbEjydfm6r1mE7DskfbzKB-0-3649847787a28851022d5cc48a677058)</p><p>![](<a href="https://secure2.wostatic.cn/static/xi9J1y6Khn6wGwUmBWEDTf/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/xi9J1y6Khn6wGwUmBWEDTf/Screenshot</a> 2023-08-23 at 15.56.37.png?auth_key=1756541792-fHQXFAcY8T4wex53N1D2YM-0-8ccf824996735952c05fe652ca581561)</p><p>![](<a href="https://secure2.wostatic.cn/static/nvkoq81dSHyBy9Zvbhao8e/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/nvkoq81dSHyBy9Zvbhao8e/Screenshot</a> 2023-08-23 at 15.56.26.png?auth_key=1756541792-w9K85MXuJpZ2BFqNmNdDHT-0-68ef4c65d3f189ad3ce5f1502c8bdafc)</p><ul><li><p>恰逢大量企业<a href="https://www.zhihu.com/search?q=%E8%A3%81%E5%91%98&amp;search_source=Entity&amp;hybrid_search_source=Entity&amp;hybrid_search_extra=%7B%22sourceType%22:%22answer%22,%22sourceId%22:2997393573%7D" target="_blank" rel="noreferrer">裁员</a>(各大公司的裁员信息)，阿里裁员、腾讯裁员、facebook的元宇宙裁员90%，微软全球裁员百分之30。招聘需求放缓，大量的悲观情绪经过一个月的酝酿，从2月中旬开始，脉脉上开始出现较密集的<strong>「前端已死」</strong>相关话题。</p></li><li><p>随后在掘金，在知乎，都要很多人讨论这个问题，常常上热榜，造成了更大范围的影响。</p><p><img src="https://secure2.wostatic.cn/static/JBHW3S6R6f7EXRq4rYamD/image.png?auth_key=1756541791-eqYFbXwbr6i3RfPtqTUXKB-0-c806fc3605925bc276d82224edee2860" alt=""></p></li></ul><h2 id="三、当前的现状" tabindex="-1">三、当前的现状 <a class="header-anchor" href="#三、当前的现状" aria-label="Permalink to “三、当前的现状”">​</a></h2><p><img src="https://secure2.wostatic.cn/static/sAVcu8kRADD1vxNcM3bnd9/image.png?auth_key=1756541791-7KZLp99VQX2YQzpRQN4sEd-0-da85a861c39c32207122df7820bfca28" alt=""></p><p>所以前端到底死没死！我这里有一些数据可以给大家分享。</p><h3 id="_3-1-官方媒体数据" tabindex="-1">3.1 官方媒体数据 <a class="header-anchor" href="#_3-1-官方媒体数据" aria-label="Permalink to “3.1 官方媒体数据”">​</a></h3><p>人民网，可能web前端是拖后腿的。</p><p>![](<a href="https://secure2.wostatic.cn/static/jNSDv8uCNnSDTs9BJATQtu/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/jNSDv8uCNnSDTs9BJATQtu/Screenshot</a> 2023-08-23 at 15.50.19.png?auth_key=1756541792-ug2RAFb3yAsXTnEQCWATPN-0-5a5224ae870695be04187d3c9dca6179)</p><h3 id="_3-2-b站小野森森调查结果" tabindex="-1">3.2 B站小野森森调查结果 <a class="header-anchor" href="#_3-2-b站小野森森调查结果" aria-label="Permalink to “3.2 B站小野森森调查结果”">​</a></h3><p><img src="https://secure2.wostatic.cn/static/2M1j9CBYooEovwPYEctYAC/image.png?auth_key=1756541791-ekFhzYePJBQCqDVZkjzQYf-0-aa299140b8781b9087f13d428ce9a6ea" alt=""></p><p><img src="https://secure2.wostatic.cn/static/oYLPLqjRiV2XvsGZ13ZC5s/image.png?auth_key=1756541792-3ZJu7znM1h4ZQfxNPLZAjr-0-67edf23f799f2071958e9bbe2ab0b2d4" alt=""></p><p>同比上一年，他结论是：</p><ul><li><ol><li>招聘预期人数低于2022年同期约50%</li></ol></li><li><ol start="2"><li>招聘达成率低于2022年同期约30%</li></ol></li><li>3.12-25k薪资区间的薪资达成平均值低于2022年同期15%</li><li><ol start="4"><li>招聘要求明显高于2022年同期水平</li></ol></li><li><ol start="5"><li>简历放弃数量高达30-40%</li></ol></li><li><ol start="6"><li>应聘人数高于2022年同期70%</li></ol></li><li><ol start="7"><li>应聘本科率高于2022年同期40%</li></ol></li><li><ol start="8"><li>面试轮数多于2022年同期</li></ol></li><li><ol start="9"><li>面试邀请率最大4%</li></ol></li><li><strong>9.offer发放率最大1.6%</strong></li></ul><p>这个数据简单来说，就是<strong>招聘的岗位减少了，应聘的人数增多了，面试要求提高了</strong>。</p><p>100个人去面试，只发了1.6个Offer。</p><p>不知道大家对这个百分之1.6有概念么？我弟今年高考，为了他选学校。我就对这种数据排名比较敏感。广西今年46万考生，百分之1.6就是7600名，这可是高本一线110多分的排名。这个分数只有我在初中的时候敢想，小学的时候选择的是清华。高考的时候就没有拿到这个排名，凭什么进了社会就可以办到呢？人不是一下子就能上进，人家在高考的时候把你赢了，找工作的时候你真的就能反超么？</p><p>我对自己是没有这么大的自信，不要拿个例当典普遍。</p><h3 id="_3-3-国外的情况" tabindex="-1">3.3 国外的情况 <a class="header-anchor" href="#_3-3-国外的情况" aria-label="Permalink to “3.3 国外的情况”">​</a></h3><p>来自Indeed的招聘指数数据：</p><p><img src="https://secure2.wostatic.cn/static/vy16LTWMezU1zajPwBjEwH/image.png?auth_key=1756541791-oUyDNaFLu8uEkzoEEXxdn2-0-920b9b83567c5373d9dc55f8ee7c7e9d" alt=""></p><p>国外的情况相比去年也是一个下降的趋势。尤其是UK，和中国一样，岗位数量是拦腰折半的。这也符合我们对于现在全球性经济大衰退的一个整体认知。</p><h3 id="_3-4-其他的有意思现象" tabindex="-1">3.4 其他的有意思现象 <a class="header-anchor" href="#_3-4-其他的有意思现象" aria-label="Permalink to “3.4 其他的有意思现象”">​</a></h3><p><img src="https://secure2.wostatic.cn/static/7ehhoWp72BUrJ8V7pbo52L/image.png?auth_key=1756541792-shDbLLovZ2LqY4YLecWUoz-0-5f1d7831d1aa1879e3565097a6e665d8" alt=""></p><p><img src="https://secure2.wostatic.cn/static/hM35oC2N3fyVgUXqN2voKv/image.png?auth_key=1756541791-wMmwxnvpzD8wq88stQvj9J-0-316948791174d97fbb931c13ef0e04af" alt=""></p><p>这张图可能有一些兄弟姐妹看过了，贴吧的一个老哥用一个公司去Boss上面发布招聘信息。</p><p>公司的背景是一个“一个0到20人小公司”。发布没几天没多久就收到300个前端，300个JAVA，200个测试的简历。我们可能掂量一下这些数据的份量。所有有一些人是海投的，也可以中侧面说明，面试者已经饥不择食了。</p><p>供过于求，完全的买方市场。</p><p>需求减少得很明显，本来一个项目还是能够进账的，但是发现把你开了能够赚得更多。</p><h3 id="_3-5-深圳具体的招聘数据" tabindex="-1">3.5 深圳具体的招聘数据 <a class="header-anchor" href="#_3-5-深圳具体的招聘数据" aria-label="Permalink to “3.5 深圳具体的招聘数据”">​</a></h3><p>左边是8月22日的最新数据。前端岗位招聘人数有3685个人。右边是今年招聘人数的趋势。有人说市场在回暖？数据没有这个表现。</p><p>![](<a href="https://secure2.wostatic.cn/static/4orAQ4vLmsNk2k9dAMxP14/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/4orAQ4vLmsNk2k9dAMxP14/Screenshot</a> 2023-08-23 at 19.48.20.png?auth_key=1756541791-pxQYvEBiLqLfu5Yd1ZmwmL-0-e135005b7d9288529d12415d8f552774)</p><p>![](<a href="https://secure2.wostatic.cn/static/rf1TbvUZTKGtR4asbB7EzE/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/rf1TbvUZTKGtR4asbB7EzE/Screenshot</a> 2023-08-23 at 19.51.58.png?auth_key=1756541791-d5U6T5wMdioKycveDcTxKC-0-004745c4e7355a17fee055563d36ac33)</p><p>深圳有多少个前端呢？ 网上搜索不到具体的数据，所以去问了文心一言，得出了这样的回答。</p><p>![](<a href="https://secure2.wostatic.cn/static/gENiV3w8E7LGQAJhm77KDo/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/gENiV3w8E7LGQAJhm77KDo/Screenshot</a> 2023-08-23 at 19.56.26.png?auth_key=1756541792-6veMQNHS65ftHwi45c4Ca4-0-f68b49d5f1c03b5a12a239c86376f826)</p><h3 id="_3-6总结" tabindex="-1">3.6总结 <a class="header-anchor" href="#_3-6总结" aria-label="Permalink to “3.6总结”">​</a></h3><p>不知道大家对于这么数据有什么感想。</p><p>‘前端已死’是一句带有情绪的话，用阮一峰的话来总结：</p><p><strong>技术发展缓慢（说一下，flutter），没有大的热点，业务重要性下降，就业机会减少</strong>。</p><p>减少前面都应该加一个形容词，那就是“大大的减少”。</p><h2 id="四、我可以怎么做" tabindex="-1">四、我可以怎么做 <a class="header-anchor" href="#四、我可以怎么做" aria-label="Permalink to “四、我可以怎么做”">​</a></h2><h3 id="_4-1正确的心态" tabindex="-1">4.1正确的心态 <a class="header-anchor" href="#_4-1正确的心态" aria-label="Permalink to “4.1正确的心态”">​</a></h3><p>我收集这些数据并不是为了传播焦虑，这些是客观现实，我必须要面对的现状。毕竟不是你的对手也不全是985 211。</p><p>既然情况已经这样了。一味地抱怨没有意义，问题还是解决的。赵本山的老图说得依旧很有道理。</p><p><img src="https://secure2.wostatic.cn/static/btqe1CCZnu7ieahHBZBFaZ/image.png?auth_key=1756541792-nEAHPxr4W6vvLyWFTgXdrH-0-fcaa0b2bf480dd533c3e4b5dee5060aa" alt=""></p><blockquote><p><em><strong>前端已死、后端已亡、测试被开、产品被裁、运维跑路、行业已黄！</strong></em></p></blockquote><p>![](<a href="https://secure2.wostatic.cn/static/9JgxpeEGBmCq4S2R6vGjot/Screenshot" target="_blank" rel="noreferrer">https://secure2.wostatic.cn/static/9JgxpeEGBmCq4S2R6vGjot/Screenshot</a> 2023-08-23 at 15.25.49.png?auth_key=1756541791-weomZbdKpZqgnuA5qyytpA-0-4d4a3c8321a18fa0634eb3b7204fdc8e)</p><p>以及对于AI的开发，出自阮一峰的文章。</p><p>老三程序员，这个是他文章的链接<a href="https://github.com/ixaxaar/VardaGPT/blob/master/STORY.md" target="_blank" rel="noreferrer">https://github.com/ixaxaar/VardaGPT/blob/master/STORY.md</a></p><p>简单的说，就是他让 ChatGPT 写一个他想要的程序，结果整整化了三个周末才跑起来。</p><p>下面就是他对 AI 的评价。</p><p>•有时我对 ChatGPT 的理解能力感到惊讶，但是更多时候，我不得不拼命推动它，朝着我想要的方向前进。它有时会产生意料之外的结果，让我感到非常沮丧。&quot;</p><p>“它像一个吸收了所有人类知识、但需要别人帮忙才能把这些知识串起来的应届毕业生。</p><p>&quot;看来我今年的工作是安全的。但是，我需要好好学习 ChatGPT，精通它的使用，让我明年也是安全的。&quot;</p><p>还是阮一峰，他的话让我听得不那么的焦虑。</p><p><strong>AI 与人类不是竞争关系，它未必会减少机会，反而可能带来更多的机会。</strong></p><p>所以好好学习ChatGTP，让它作为放大自己生产力的工具才是我们正确的态度。</p><p>总结一下，就是做好以下心里准备：</p><ul><li>直面现实</li><li>保持学习</li></ul><h3 id="_4-2-我可以选择的路" tabindex="-1">4.2 我可以选择的路 <a class="header-anchor" href="#_4-2-我可以选择的路" aria-label="Permalink to “4.2 我可以选择的路”">​</a></h3><p>如果“前端已死”不再是一句情绪的话，而成为我的现实呢？被裁了。应该怎么办？所以我把可以走的路都列了出来。</p><img src="https://yoran-images-1256970527.cos.ap-guangzhou.myqcloud.com/%E6%88%91%E6%9C%89%E4%BB%80%E4%B9%88%E8%B7%AF%E5%8F%AF%E4%BB%A5%E8%B5%B0.png"><p>国内情况不好，国外也不乐观，但是如果我们可以吧国内和国外都作为选择项呢？</p><p>所以，除了英语的能力之外，所有需要的技能都有一个公约数，那就是<strong>学习能力</strong>。</p><p><img src="https://secure2.wostatic.cn/static/94BCKPFwDgVZVR13qgiZiM/image.png?auth_key=1756541792-6dBq3et8e7hhJGdDuzHwQ-0-268b818dd4a56ea40fce05c7d207ac05" alt=""></p><p>如果对于在舒适圈中的前端这个方向，我都不能学下去，我还能从哪里锻炼自己的学习能力呢？</p><p><img src="https://secure2.wostatic.cn/static/uX1C48rWMxXWvJtafHuRvP/image.png?auth_key=1756541792-9kj72r4TCtFRoBso8jve2Q-0-ba58fd6a50ff8fb97531d2d9282b2a71" alt=""></p><p><strong>如果在自己的舒适圈内，都没有把事情做好，真到了需要转行的时候，我凭什么就能干好其他事情。</strong>这是不现实的。</p><p>这就是为什么我都要失业了，还要和大家讨论函数式是什么？代码如何组织？这就是为什么我们依旧在组织分享，组织技术分享。你们都没有尽力的在自己的舒适圈里面把本职工作做得的很好。有什么资格抱怨大环境，有什么理由在担心未来。行业的起升又和你有什么关系？</p><p>有一段话我觉得很有道理：为什么我似乎懂得了很多道理，但是依旧过不好这一生。为什么呢？是因为我们自以为自己懂得了这些那些的道理，但是我过往的那些认知都是通过短视频，通过知乎，这些都是别人灌输给我的结论，这些是自己的东西么？一年看了几本书了？去过什么地方了？深入什么到行业了么？了解这些行业的底层逻辑吗？才20多岁，最多30岁出头，懂个屁。</p><blockquote><p>这句话是骂我自己的，惊醒我自己的。我感觉我身边都是卷王。</p></blockquote><p>另一方面，【前端已死】它其实是一个很大的问题，我们为什么活得这么累啊，就是因为我经常活在宏观述说当中。【前端已死】能够牵扯到的东西太大，中美对抗、俄乌冲突、全球经济周期性下滑，国际资本投资，没有一样是我能够影响的。如果每天都因为这些事情去网上和别人打嘴炮的话，对自己的生活没有任何意义。我能够影响到只有我写的代码。做好自己份内的工作，就是对这个社会最大的贡献！</p><blockquote><p>这些话都是在骂我自己</p></blockquote>',86)]))}const f=t(s,[["render",p]]);export{b as __pageData,f as default};
